from ledger.wallet import InsufficientFunds

WALLETS = ["merchant-17", "merchant-3", "merchant-9", "pair-a", "pair-b", "pair-c", "pair-d"]
START = {"merchant-17": 400, "merchant-3": 1200, "merchant-9": 800,
         "pair-a": 500, "pair-b": 500, "pair-c": 500, "pair-d": 500}


def run_with_timeout(fn, seconds):
    """Run fn in a thread; return True if it finished within seconds (False means it hung)."""
    t = threading.Thread(target=fn, daemon=True)
    t.start()
    return join_all([t], seconds)


def join_all(threads, seconds):
    """Join every thread against one shared deadline; True when all have finished."""
    deadline = time.monotonic() + seconds
    for t in threads:
        t.join(max(0.0, deadline - time.monotonic()))
    return not any(t.is_alive() for t in threads)


class FileStore:
    """The store interface shared by separate processes through files in one directory.

    Balances live in one JSON file, and every access to it holds an flock on balances.lock.
    lock(key) holds an flock on a per-key file. flock is held per open file, so it coordinates
    separate processes (and threads) on this machine. The sandbox blocks sockets, so a Manager
    can't serve as the shared service here; this stands in for the shared service that
    ledger/store.py's docstring describes.
    """

    def __init__(self, directory):
        self._dir = directory
        self._data_path = os.path.join(directory, "balances.json")
        self._data_lock = os.path.join(directory, "balances.lock")
        with open(self._data_path, "w") as f:
            json.dump({}, f)

    @contextlib.contextmanager
    def _flocked(self, path):
        with open(path, "a+") as f:
            fcntl.flock(f, fcntl.LOCK_EX)
            try:
                yield
            finally:
                fcntl.flock(f, fcntl.LOCK_UN)

    def _read(self):
        with open(self._data_path) as f:
            return json.load(f)

    def _write(self, data):
        with open(self._data_path, "w") as f:
            json.dump(data, f)

    def get(self, key):
        with self._flocked(self._data_lock):
            return self._read().get(key)

    def put(self, key, value):
        with self._flocked(self._data_lock):
            data = self._read()
            data[key] = value
            self._write(data)

    def compare_and_put(self, key, expected, value):
        with self._flocked(self._data_lock):
            data = self._read()
            if data.get(key) != expected:
                return False
            data[key] = value
            self._write(data)
            return True

    @contextlib.contextmanager
    def lock(self, key):
        with self._flocked(os.path.join(self._dir, "wallet-%s.lock" % key)):
            yield


class WalletSemanticsTest(unittest.TestCase):
