        for w, v in START.items():
            self.store.put(w, v)

    def balances(self):
        return {w: self.store.get(w) for w in START}

    def test_credit_adds_to_balance(self):
        wallet.credit(self.store, "merchant-17", 40)
        self.assertEqual(self.store.get("merchant-17"), 440)

    def test_credit_to_unseen_wallet(self):
        wallet.credit(self.store, "new", 7)
        self.assertEqual(wallet.balance(self.store, "new"), 7)

    def test_transfer_moves_money(self):
        wallet.transfer(self.store, "merchant-3", "merchant-9", 15)
        self.assertEqual(self.store.get("merchant-3"), 1185)
        self.assertEqual(self.store.get("merchant-9"), 815)

    def test_transfer_can_empty_wallet(self):
        wallet.transfer(self.store, "pair-a", "pair-b", 500)
        self.assertEqual(self.store.get("pair-a"), 0)
        self.assertEqual(self.store.get("pair-b"), 1000)

    def test_overdraft_refused_and_changes_nothing(self):
        before = self.balances()
        with self.assertRaises(InsufficientFunds):
            wallet.transfer(self.store, "pair-a", "pair-b", 501)
        self.assertEqual(self.balances(), before)

    def test_overdraft_leaves_locks_released(self):
        with self.assertRaises(InsufficientFunds):
            wallet.transfer(self.store, "pair-a", "pair-b", 501)
        self.assertTrue(run_with_timeout(lambda: self._take_both("pair-a", "pair-b"), 5))

    def _take_both(self, a, b):
        with self.store.lock(a):
            with self.store.lock(b):
                pass

    def test_self_transfer_changes_nothing(self):
        before = self.balances()
        self.assertTrue(run_with_timeout(
            lambda: wallet.transfer(self.store, "merchant-17", "merchant-17", 100), 5))
        self.assertEqual(self.balances(), before)

    def test_self_transfer_over_balance_refused_and_changes_nothing(self):
