def make_jobs(seed, count):
    """A random mix of credits, opposite and disjoint transfers, overdrafts and self-transfers."""
    rng = random.Random(seed)
    jobs = []
    for _ in range(count):
        r = rng.random()
        if r < 0.20:
            jobs.append(("credit", "merchant-17", rng.randint(1, 50)))
        elif r < 0.30:
            jobs.append(("credit", rng.choice(WALLETS), rng.randint(1, 50)))
        elif r < 0.50:
            # opposite-direction transfers between one pair: the ABBA deadlock in the incident
            a, b = rng.choice([("merchant-3", "merchant-9"), ("merchant-9", "merchant-3")])
            jobs.append(("transfer", a, b, rng.randint(1, 80)))
        elif r < 0.65:
            # disjoint pairs, never touching the merchant wallets
            a, b = rng.choice([("pair-a", "pair-b"), ("pair-b", "pair-a"),
                               ("pair-c", "pair-d"), ("pair-d", "pair-c")])
            jobs.append(("transfer", a, b, rng.randint(1, 120)))
        elif r < 0.80:
            # overdraft attempts: far more than any wallet holds
            a, b = rng.sample(WALLETS, 2)
            jobs.append(("transfer", a, b, rng.randint(5000, 10000)))
        elif r < 0.90:
            a = rng.choice(WALLETS)
            jobs.append(("transfer", a, a, rng.randint(1, 60)))
        else:
            a, b = rng.sample(["merchant-17", "merchant-3", "merchant-9"], 2)
            jobs.append(("transfer", a, b, rng.randint(1, 60)))
    return jobs


def stress_child(store, jobs, barrier, out):
    barrier.wait(timeout=60)
    lines = []
    worker.run(store, jobs, log=lines.append)
    out.put(lines)


def applied_deltas(lines, deltas, tally):
    """Fold the worker's 'done' lines into per-wallet deltas; tally counts credits and refusals."""
    for line in lines:
        if " refused: " in line:
            tally["refused"] += 1
            continue
        if not line.endswith(" done"):
            continue
        kind, rest = line.split(" ", 1)
        args = ast.literal_eval(rest[:-len(" done")])
        if kind == "credit":
            w, c = args
            deltas[w] = deltas.get(w, 0) + c
            tally["credited"] += c
        else:
            src, dst, c = args
            deltas[src] = deltas.get(src, 0) - c
            deltas[dst] = deltas.get(dst, 0) + c  # src == dst nets to zero


class MultiProcessStressTest(unittest.TestCase):
    PROCESSES = 6
    JOBS_PER_PROCESS = 300
    TIMEOUT = 60

    def run_stress(self, seed):
        directory = tempfile.mkdtemp()
        procs = []
        try:
            store = FileStore(directory)
            for w, v in START.items():
                store.put(w, v)
            barrier = mp.Barrier(self.PROCESSES)
            out = mp.Queue()
            job_sets = [make_jobs(seed * 100 + i, self.JOBS_PER_PROCESS) for i in range(self.PROCESSES)]
            for jobs in job_sets:
                p = mp.Process(target=stress_child, args=(store, jobs, barrier, out))
                p.start()
                procs.append(p)

            deltas, tally = {}, {"credited": 0, "refused": 0}
            for _ in procs:
                try:
                    lines = out.get(timeout=self.TIMEOUT)
                except queue.Empty:
                    self.fail(f"seed {seed}: a worker never finished (hang or deadlock)")
                applied_deltas(lines, deltas, tally)

            for p in procs:
                p.join(10)
                self.assertFalse(p.is_alive(), f"seed {seed}: worker still running after finishing")
                self.assertEqual(p.exitcode, 0, f"seed {seed}: worker exited with {p.exitcode}")

            final = {w: store.get(w) for w in WALLETS}
            self.assertEqual(sum(final.values()), sum(START.values()) + tally["credited"],
                             f"seed {seed}: money not conserved")
            expected = {w: START[w] + deltas.get(w, 0) for w in WALLETS}
            self.assertEqual(final, expected, f"seed {seed}: balances differ from applied ops")
            self.assertTrue(all(v >= 0 for v in final.values()), f"seed {seed}: negative {final}")
            self.assertGreater(tally["refused"], 0, "overdraft attempts were not exercised")
            return final
        finally:
            for p in procs:
                if p.is_alive():
                    p.terminate()
            shutil.rmtree(directory, ignore_errors=True)

    def test_several_seeds(self):
        for seed in range(3):
            self.run_stress(seed)


if __name__ == "__main__":
    unittest.main()
